mapper.select:
select  from lab_ipr i join lab_member m on m.id=i.owner_id and m.del_flag='0'
join sys_user u on u.user_id=m.user_id and u.del_flag='0' where i.del_flag='0'
and i.id=#{id}and i.owner_id=#{ownerId}
and i.ipr_type=#{iprType}and i.ipr_stage=#{iprStage}
and i.status=#{status}and i.ipr_name like concat('%',#{iprName},'%')
order by i.status,i.planned_submit_date,i.id
